/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
final class METInventTransferTable_AdhocTest
{
}

Method.Source:
    /// <summary>
    /// Class entry point. The system will call this method when a designated menu 
    /// is selected or when execution starts and this class is set as the startup class.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        METInventTransferTable_AdhocTest instance = new METInventTransferTable_AdhocTest();
        instance.run();

        info("@MET:Finished");
    }

    /// <summary>
    /// run
    /// </summary>
    public void run()
    {
        InventTransferTable inventTransferTable;
        METInventTransferTableExt inventTransferTableExt;

        ttsbegin;
        inventTransferTable.clear();
        inventTransferTable.initValue();
        inventTransferTable.InventLocationIdFrom = "007";
        inventTransferTable.InventLocationIdTo = "017";

        inventTransferTableExt = inventTransferTable.metInventTransferTableExt();
        inventTransferTableExt.allowBackOrder = NoYes::Yes;
        inventTransferTable.metPackMETInventTransferTableExt(inventTransferTableExt);
        
        inventTransferTable.insert();
        ttscommit;

        ttsbegin;
        inventTransferTable.readPast();
        inventTransferTable.selectForUpdate(true);
        
        inventTransferTableExt = inventTransferTable.metInventTransferTableExt();
        inventTransferTableExt.AutoExtract = NoYes::Yes;
        inventTransferTable.metPackMETInventTransferTableExt(inventTransferTableExt);

        inventTransferTable.update();
        ttscommit;



    }
